effect.shader:
const vec3 gmLuma = vec3(0.2126, 0.7152, 0.0722);
float gmHash21(vec2 p) {
return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
float gmNoise(vec2 p) {
vec2 i = floor(p);
vec2 f = fract(p);
vec2 u = f * f * (3.0 - 2.0 * f);
return mix(mix(gmHash21(i), gmHash21(i + vec2(1.0, 0.0)), u.x),
mix(gmHash21(i + vec2(0.0, 1.0)), gmHash21(i + vec2(1.0, 1.0)), u.x), u.y);
}
float gmPotential(vec2 p, float t) {
mat2 turn = mat2(0.8, -0.6, 0.6, 0.8);
p = p * scale + seed * vec2(1.71, 2.43);
float n0 = gmNoise(p + vec2(t * 0.11, -t * 0.07));
p = turn * p * 2.03 + vec2(4.7, 8.2);
float n1 = gmNoise(p - vec2(t * 0.09, t * 0.13));
p = turn * p * 2.01 + vec2(9.1, 3.4);
float n2 = gmNoise(p + vec2(t * 0.17, t * 0.05));
float detailed = n0 * 0.5714286 + n1 * 0.2857143 + n2 * 0.1428571;
return mix(detailed, n0, viscosity);
}
vec2 gmVelocity(vec2 p, float t) {
const float e = 0.015;
float leftValue = gmPotential(p - vec2(e, 0.0), t);
float rightValue = gmPotential(p + vec2(e, 0.0), t);
float downValue = gmPotential(p - vec2(0.0, e), t);
float upValue = gmPotential(p + vec2(0.0, e), t);
vec2 gradient = vec2(rightValue - leftValue, upValue - downValue) / (2.0 * e);
return vec2(gradient.y, -gradient.x) * vorticity;
}
void main() {
vec2 uv = acScreenNorm;
vec2 texSize = max(inputImg.size, vec2(1.0));
float aspect = texSize.x / texSize.y;
vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
float t = evolution + (autoAnimate ? acTime * speed : 0.0);
float dt = strength * 0.035;
vec2 velocityA = gmVelocity(p, t);
vec2 midpoint = p - velocityA * dt * 0.5;
vec2 velocityB = gmVelocity(midpoint, t);
vec2 advectedPoint = p - velocityB * dt;
vec2 advectedUv = uv + (advectedPoint - p) / vec2(aspect, 1.0);
advectedUv = 1.0 - abs(mod(advectedUv, 2.0) - 1.0);
vec4 src = texture2DCv(inputImg.texture, uv);
vec4 moved = texture2DCv(inputImg.texture, advectedUv);
float flowValue = gmPotential(advectedPoint, t);
float tone = dot(moved.rgb, gmLuma);
float inkMask = clamp((tone - 0.5) * inkContrast + 0.5 + (flowValue - 0.5) * 0.35, 0.0, 1.0);
vec3 inkColor = mix(inkColorA.rgb, inkColorB.rgb, smoothstep(0.0, 1.0, inkMask));
vec3 colored = mix(moved.rgb, inkColor * max(moved.a, 0.0001), inkAmount);
vec4 result = vec4(colored, moved.a);
gl_FragColor = mix(src, result, clamp(mixAmount, 0.0, 1.0));
}
